48	/****************************************************************************
49	 * 创建主界面
50	 ****************************************************************************/
51	
52	static void create_main_ui(void)
53	{
54	  lv_obj_t *scr = lv_screen_active();
55	
56	  /* 深色背景 */
57	
58	  lv_obj_set_style_bg_color(scr, COLOR_BG_DARK, 0);
59	  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
60	
61	  /* 时钟组件 */
62	
63	  clock_widget_create(scr);
64	
65	  /* 测试按钮区域 */
66	
67	  lv_obj_t *btn_cont = lv_obj_create(scr);
68	  lv_obj_set_size(btn_cont, 350, 240);
69	  lv_obj_align(btn_cont, LV_ALIGN_TOP_MID, 0, 210);
70	  lv_obj_set_style_bg_opa(btn_cont, LV_OPA_TRANSP, 0);
71	  lv_obj_set_style_border_width(btn_cont, 0, 0);
72	  lv_obj_set_style_pad_all(btn_cont, 0, 0);
73	  lv_obj_remove_flag(btn_cont, LV_OBJ_FLAG_SCROLLABLE);
74	
75	  lv_obj_set_flex_flow(btn_cont, LV_FLEX_FLOW_COLUMN);
76	  lv_obj_set_flex_align(btn_cont, LV_FLEX_ALIGN_CENTER,
77	                         LV_FLEX_ALIGN_CENTER,
78	                         LV_FLEX_ALIGN_CENTER);
79	  lv_obj_set_style_pad_row(btn_cont, 12, 0);
80	
81	  /* 测试按钮 */
82	
83	  ui_create_button(btn_cont, 280, 46, "弹窗测试", btn_popup_cb);
84	  ui_create_button(btn_cont, 280, 46, "课程提醒：高数", btn_reminder_cb);
85	  ui_create_button(btn_cont, 280, 46, "课程提醒：嵌入式", btn_reminder2_cb);
86	
87	  /* 底部版本信息 */
88	
89	  lv_obj_t *ver = ui_create_label(scr, "Day 2 UI Demo — Team 307",
90	                                  FONT_TINY, COLOR_TEXT_GRAY);
91	  lv_obj_align(ver, LV_ALIGN_BOTTOM_MID, 0, -16);
92	}
