95	 * 主函数
96	 ****************************************************************************/
97	
98	int main(int argc, FAR char *argv[])
99	{
100	  lv_nuttx_dsc_t    dsc;
101	  lv_nuttx_result_t result;
102	  uint32_t          idle;
103	
104	  printf("=== Day 2 UI Demo (Team 307) ===\n");
105	
106	  /* 检查 LVGL 是否已初始化 */
107	
108	  if (lv_is_initialized())
109	    {
110	      printf("ERROR: LVGL already initialized by another app.\n");
111	      printf("Please stop the other app first, or disable CONFIG_QUICKAPP.\n");
112	      return -1;
113	    }
114	
115	  /* LVGL 初始化 */
116	
117	  lv_init();
118	  lv_nuttx_dsc_init(&dsc);
119	
120	  dsc.fb_path    = "/dev/lcd0";
121	  dsc.input_path = "/dev/input0";
122	
123	  lv_nuttx_init(&dsc, &result);
124	
125	  if (result.disp == NULL)
126	    {
127	      printf("ERROR: display init failed\n");
128	      return -1;
129	    }
130	
131	  printf("Display: %dx%d\n", SCREEN_WIDTH, SCREEN_HEIGHT);
132	
133	  /* 创建主界面 */
134	
135	  create_main_ui();
136	
137	  printf("UI ready. Main loop running.\n");
138	
139	  /* 主循环 */
140	
141	  while (1)
142	    {
143	      idle = lv_timer_handler();
144	      idle = idle ? idle : 1;
145	      usleep(idle * 1000);
146	    }
147	
148	  lv_nuttx_deinit(&result);
149	  lv_deinit();
150	
151	  return 0;
152	}
