234	#if defined(CONFIG_I2C) && defined(CONFIG_SENSORS_LSM6DSL)
235	static int sf32lb52_lsm6ds3_initialize(FAR struct i2c_master_s *i2c)
236	{
237	  int ret;
238	
239	  /* LSM6DS3TR-C is register-compatible enough with the in-tree LSM6DSL
240	   * test driver for board bringup.  The board wiring is:
241	   *   PA39 - I2C2 SDA
242	   *   PA40 - I2C2 SCL
243	   *   PA31 - INT
244	   *   PA30 - sensor LDO enable, active high
245	   */
246	
247	  HAL_PIN_Set(PAD_PA30, GPIO_A30, PIN_NOPULL, 1);
248	  sifli_gpio_config(SF32LB52_LSM6DS3_LDO_PIN, GPIO_OUTPUT);
249	  sifli_gpio_write(SF32LB52_LSM6DS3_LDO_PIN, true);
250	  usleep(10000);
251	
252	  HAL_PIN_Set(PAD_PA31, GPIO_A31, PIN_PULLUP, 1);
253	  sifli_gpio_config(SF32LB52_LSM6DS3_INT_PIN, GPIO_INPUT);
254	
255	  ret = lsm6dsl_sensor_register(SF32LB52_LSM6DS3_DEVPATH,
256	                                i2c,
257	                                LSM6DSLACCEL_ADDR0);
258	  if (ret < 0)
259	    {
260	      syslog(LOG_WARNING,
261	             "WARN: LSM6DS3 not found at 0x%02x on I2C%d: %d\n",
262	             LSM6DSLACCEL_ADDR0, SF32LB52_LSM6DS3_I2C_BUS, ret);
263	
264	      ret = lsm6dsl_sensor_register(SF32LB52_LSM6DS3_DEVPATH,
265	                                    i2c,
266	                                    LSM6DSLACCEL_ADDR1);
267	    }
268	
269	  if (ret < 0)
270	    {
271	      syslog(LOG_ERR,
272	             "ERROR: LSM6DS3 register failed on I2C%d: %d\n",
273	             SF32LB52_LSM6DS3_I2C_BUS, ret);
274	      return ret;
275	    }
276	
277	  syslog(LOG_INFO,
278	         "INFO: LSM6DS3 test device registered as %s, INT=%d\n",
279	         SF32LB52_LSM6DS3_DEVPATH, SF32LB52_LSM6DS3_INT_PIN);
280	  return OK;
281	}
282	#endif
