327	/****************************************************************************
328	 * Name: sf32lb52_lchspi_ulp_bringup
329	 *
330	 * Description:
331	 *   Perform architecture-specific initialization
332	 *
333	 *   CONFIG_BOARD_LATE_INITIALIZE=y
334	 *     Called from board_late_initialize().
335	 *
336	 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y
337	 *     Called from the NSH library
338	 *
339	 ****************************************************************************/
340	
341	int sf32lb52_lchspi_ulp_bringup(void)
342	{
343	  int ret = OK;
344	  int tmpret;
345	
346	#ifdef CONFIG_FS_PROCFS
347	  tmpret = mkdir("/proc", 0755);
348	  if (tmpret < 0 && errno != EEXIST)
349	    {
350	      serr("WARN: mkdir /proc failed: %d\n", errno);
351	    }
352	
353	  tmpret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
354	  if (tmpret < 0 && tmpret != -EBUSY)
355	    {
356	      serr("WARN: mount procfs failed: %d\n", tmpret);
357	    }
358	#endif
359	
360	  tmpret = mkdir("/data", 0755);
361	  if (tmpret < 0 && errno != EEXIST)
362	    {
363	      serr("WARN: mkdir /data failed: %d\n", errno);
364	    }
365	
366	#ifdef CONFIG_FS_TMPFS
367	  /* Keep /data writable for syscall and file API test cases. */
368	  tmpret = nx_mount(NULL, "/data", "tmpfs", 0, NULL);
369	  if (tmpret < 0 && tmpret != -EBUSY)
370	    {
371	      serr("WARN: mount tmpfs on /data failed: %d\n", tmpret);
372	    }
373	#endif
374	
375	#if defined(CONFIG_RTC) && defined(CONFIG_RTC_DRIVER)
376	  struct rtc_lowerhalf_s *rtclower = NULL;
377	
378	  rtclower = sf32lb_rtc_lowerhalf();
379	  if (rtclower == NULL)
380	    {
381	      serr("ERROR: Failed to instantiate RTC lower-half\n");
382	      return -ENOMEM;
383	    }
384	
385	  ret = rtc_initialize(0, rtclower);
386	  if (ret < 0)
387	    {
388	      serr("ERROR: rtc_initialize failed: %d\n", ret);
389	      return ret;
390	    }
391	#endif
392	
393	#ifdef CONFIG_ADC
394	  ret = sf32lb_adc_init("/dev/adc0");
395	  if (ret < 0)
396	    {
397	      serr("ERROR: sf32lb_adc_init failed: %d\n", ret);
398	      return ret;
399	    }
400	#endif
401	
402	#ifdef CONFIG_DEV_GPIO
403	  ret = sifli_gpio_initialize();
404	  if (ret < 0)
405	    {
406	      syslog(LOG_ERR, "ERROR: sifli_gpio_initialize failed: %d\n", ret);
407	      return ret;
408	    }
409	#endif
410	
411	#ifdef CONFIG_TIMER
412	#if SF32LB_TIMER_DEFAULT_INDEX >= 0
413	  {
414	    FAR struct timer_lowerhalf_s *timer_lower;
415	    FAR void *timer_upper;
416	
417	    timer_lower = sf32lb_timer_initialize(SF32LB_TIMER_DEFAULT_INDEX,
418	                                          1000000);
419	    if (timer_lower == NULL)
420	      {
421	        syslog(LOG_ERR, "ERROR: sf32lb_timer_initialize failed\n");
422	        return -ENODEV;
423	      }
424	
425	    timer_upper = timer_register("/dev/timer0", timer_lower);
426	    if (timer_upper == NULL)
427	      {
428	        ret = -errno;
429	        syslog(LOG_ERR, "ERROR: timer_register(/dev/timer0) failed: %d\n",
