612	/****************************************************************************
613	 * Name: board_early_initialize
614	 *
615	 * Description:
616	 *   If CONFIG_BOARD_EARLY_INITIALIZE is selected, then an additional
617	 *   initialization call will be performed in the boot-up sequence to a
618	 *   function called board_early_initialize().  board_early_initialize()
619	 *   will be called immediately after up_initialize() and well before
620	 *   board_early_initialize() is called and the initial application is
621	 *   started.  The context in which board_early_initialize() executes is
622	 *   suitable for early initialization of most, simple device drivers and
623	 *   is a logical, board-specific extension of up_initialize().
624	 *
625	 *   board_early_initialize() runs on the startup, initialization thread.
626	 *   Some initialization operations cannot be performed on the start-up,
627	 *   initialization thread.  That is because the initialization thread
628	 *   cannot wait for event.  Waiting may be required, for example, to
629	 *   mount a file system or or initialize a device such as an SD card.
630	 *   For this reason, such driver initialize must be deferred to
631	 *   board_late_initialize().
632	
633	 ****************************************************************************/
634	
635	#ifdef CONFIG_BOARD_EARLY_INITIALIZE
636	void board_early_initialize(void)
637	{
638	
639	}
640	#endif
641	
642	/****************************************************************************
643	 * Name: board_late_initialize
644	 *
645	 * Description:
646	 *   If CONFIG_BOARD_LATE_INITIALIZE is selected, then an additional
647	 *   initialization call will be performed in the boot-up sequence to a
648	 *   function called board_late_initialize().  board_late_initialize() will
649	 *   be called after up_initialize() and board_early_initialize() and just
650	 *   before the initial application is started.  This additional
651	 *   initialization phase may be used, for example, to initialize board-
652	 *   specific device drivers for which board_early_initialize() is not
653	 *   suitable.
654	 *
655	 *   Waiting for events, use of I2C, SPI, etc are permissible in the context
656	 *   of board_late_initialize().  That is because board_late_initialize()
657	 *   will run on a temporary, internal kernel thread.
658	 *
659	 ****************************************************************************/
660	
661	#ifdef CONFIG_BOARD_LATE_INITIALIZE
662	void board_late_initialize(void)
663	{
664	  /* Perform board-specific initialization */
665	
666	  sf32lb52_lchspi_ulp_bringup();
667	}
668	#endif
