112	static void ft6146_data_worker(void *param)
113	{
114	  struct ft6146_touch_lowerhalf_s *ft6146 =
115	    (struct ft6146_touch_lowerhalf_s *)param;
116	  struct touch_sample_s sample;
117	  uint8_t buf[5] = {0};
118	  uint8_t touch_num;
119	  int ret;
120	
121	  ret = ft6146_i2c_read(ft6146->i2c, FT6146_REG_TD_STATUS, buf, sizeof(buf));
122	  if (ret < 0)
123	    {
124	      ierr("ft6146: read touch data failed: %d\n", ret);
125	      return;
126	    }
127	
128	  touch_num = buf[0] & 0x0f;
129	
130	  sample.npoints = 1;
131	  if (touch_num > 0)
132	    {
133	      ft6146->last_x = ((uint16_t)(buf[1] & 0x0f) << 8) | buf[2];
134	      ft6146->last_y = ((uint16_t)(buf[3] & 0x0f) << 8) | buf[4];
135	      sample.point[0].flags = TOUCH_DOWN;
136	    }
137	  else
138	    {
139	      sample.point[0].flags = TOUCH_UP;
140	    }
141	
142	  sample.point[0].x = ft6146->last_x;
143	  sample.point[0].y = ft6146->last_y;
144	
145	  touch_event(ft6146->lower.priv, &sample);
146	}
147	
148	static void ft6146_irq_handler(void *arg)
149	{
150	  struct ft6146_touch_lowerhalf_s *ft6146 =
151	    (struct ft6146_touch_lowerhalf_s *)arg;
152	  int ret;
153	
154	  ret = work_queue(HPWORK, &ft6146->work, ft6146_data_worker, ft6146, 0);
155	  DEBUGASSERT(ret == OK);
156	}
157	
158	static int ft6146_hw_init(struct ft6146_touch_lowerhalf_s *ft6146)
159	{
160	  uint8_t id_h = 0;
161	  uint8_t id_l = 0;
162	  int ret;
163	
164	  BSP_TP_PowerUp();
165	  BSP_TP_Reset(0);
166	  usleep(5000);
167	  BSP_TP_Reset(1);
168	  usleep(80000);
169	
170	  ret = sifli_gpio_config(ft6146->pin_irq, GPIO_INPUT);
171	  if (ret < 0)
172	    {
173	      ierr("ft6146: irq pin config failed: %d\n", ret);
174	      return ret;
175	    }
176	
177	  ret = ft6146_i2c_read(ft6146->i2c, FT6146_REG_ID_H, &id_h, 1);
178	  if (ret < 0)
179	    {
180	      ierr("ft6146: read id_h failed: %d\n", ret);
181	      return ret;
182	    }
183	
184	  ret = ft6146_i2c_read(ft6146->i2c, FT6146_REG_ID_L, &id_l, 1);
185	  if (ret < 0)
186	    {
187	      ierr("ft6146: read id_l failed: %d\n", ret);
188	      return ret;
189	    }
190	
191	  iinfo("ft6146 id_h=0x%02x id_l=0x%02x\n", id_h, id_l);
192	
193	  ret = sifli_gpio_set_event(ft6146->pin_irq, false, true,
194	                             ft6146_irq_handler, ft6146);
195	  if (ret < 0)
196	    {
197	      ierr("ft6146: irq event setup failed: %d\n", ret);
198	      return ret;
199	    }
200	
201	  return OK;
202	}
203	
204	static ssize_t ft6146_touch_notify(FAR void *input_lower,
205	                                   FAR const char *buffer,
206	                                   size_t buflen)
207	{
208	  FAR struct ft6146_touch_lowerhalf_s *ft6146 =
209	    (FAR struct ft6146_touch_lowerhalf_s *)input_lower;
210	  FAR const struct touch_sample_s *sample =
211	    (FAR const struct touch_sample_s *)buffer;
212	
213	  touch_event(ft6146->lower.priv, sample);
214	  return buflen;
215	}
216	
217	static ssize_t ft6146_touch_write(FAR struct touch_lowerhalf_s *input_lower,
218	                                  FAR const char *buffer,
219	                                  size_t buflen)
220	{
221	  FAR struct ft6146_touch_lowerhalf_s *ft6146 =
222	    (FAR struct ft6146_touch_lowerhalf_s *)input_lower;
223	
224	  return ft6146_touch_notify(ft6146, buffer, buflen);
225	}
226	
227	/****************************************************************************
228	 * Public Functions
229	 ****************************************************************************/
230	
231	int ft6146_touch_initialize(struct i2c_master_s *i2c, uint32_t irq_pin)
232	{
233	  FAR struct ft6146_touch_lowerhalf_s *ft6146;
234	  int ret;
235	
236	  DEBUGASSERT(i2c != NULL);
237	
238	  ft6146 = kmm_zalloc(sizeof(struct ft6146_touch_lowerhalf_s));
239	  if (ft6146 == NULL)
240	    {
241	      return -ENOMEM;
242	    }
243	
244	  ft6146->lower.write = ft6146_touch_write;
245	  ft6146->lower.maxpoint = 1;
246	  ft6146->i2c = i2c;
247	  ft6146->pin_irq = irq_pin;
248	
249	  nxmutex_init(&ft6146->devlock);
250	  nxsem_init(&ft6146->waitsem, 0, 0);
251	
252	  ret = touch_register(&ft6146->lower, "/dev/" FT6146_NAME_TOUCH, 16);
253	  if (ret < 0)
254	    {
255	      nxmutex_destroy(&ft6146->devlock);
256	      nxsem_destroy(&ft6146->waitsem);
257	      kmm_free(ft6146);
258	      return ret;
259	    }
260	
261	  ret = ft6146_hw_init(ft6146);
262	  if (ret < 0)
263	    {
264	      touch_unregister(&ft6146->lower, "/dev/" FT6146_NAME_TOUCH);
265	      nxmutex_destroy(&ft6146->devlock);
266	      nxsem_destroy(&ft6146->waitsem);
267	      kmm_free(ft6146);
268	      return ret;
269	    }
270	
271	  return OK;
272	}
